import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in), m = (int) readLong(in);
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = readLong(in);
        // the intersection of all intervals is [max of left ends, min of right ends]
        long lo = Long.MIN_VALUE, hi = Long.MAX_VALUE;
        for (int i = 0; i < m; i++) {
            lo = Math.max(lo, readLong(in));
            hi = Math.min(hi, readLong(in));
        }
        long count = 0;
        for (long x : a) if (lo <= x && x <= hi) count++;
        System.out.println(count);
    }

    static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int64 {
		sc.Scan()
		v, _ := strconv.ParseInt(sc.Text(), 10, 64)
		return v
	}
	n, m := int(next()), int(next())
	a := make([]int64, n)
	for i := range a {
		a[i] = next()
	}
	// the intersection of all intervals is [max of left ends, min of right ends]
	var lo, hi int64 = math.MinInt64, math.MaxInt64
	for i := 0; i < m; i++ {
		lo = max(lo, next())
		hi = min(hi, next())
	}
	count := 0
	for _, x := range a {
		if lo <= x && x <= hi {
			count++
		}
	}
	fmt.Println(count)
}
